// 简化版腾讯地图API调用类
class QQMapWX {
  constructor(options) {
    this.key = options.key;
    this.baseUrl = 'https://apis.map.qq.com/ws/';
  }

  // 地点搜索API
  search(options) {
    const url = `${this.baseUrl}place/v1/search?`;
    const params = {
      keyword: options.keyword,
      boundary: options.boundary || 'region(北京市,0)',
      page_size: options.page_size || 10,
      page_index: options.page_index || 1,
      output: 'json',
      key: this.key
    };

    return new Promise((resolve, reject) => {
      wx.request({
        url: url + this._objToStr(params),
        method: 'GET',
        success: res => {
          if (res.data.status === 0) {
            options.success && options.success(res.data);
            resolve(res.data);
          } else {
            options.fail && options.fail(res.data);
            reject(res.data);
          }
        },
        fail: err => {
          options.fail && options.fail(err);
          reject(err);
        },
        complete: res => {
          options.complete && options.complete(res);
        }
      });
    });
  }

  // 坐标转换API
  translateCoord(options) {
    const url = `${this.baseUrl}coord/v1/translate?`;
    const params = {
      locations: options.locations,
      type: options.type || 1,
      output: 'json',
      key: this.key
    };

    return new Promise((resolve, reject) => {
      wx.request({
        url: url + this._objToStr(params),
        method: 'GET',
        success: res => {
          if (res.data.status === 0) {
            options.success && options.success(res.data);
            resolve(res.data);
          } else {
            options.fail && options.fail(res.data);
            reject(res.data);
          }
        },
        fail: err => {
          options.fail && options.fail(err);
          reject(err);
        },
        complete: res => {
          options.complete && options.complete(res);
        }
      });
    });
  }

  // 对象转字符串
  _objToStr(obj) {
    return Object.keys(obj)
      .map(key => `${encodeURIComponent(key)}=${encodeURIComponent(obj[key])}`)
      .join('&');
  }
}

module.exports = QQMapWX;
